import re
import sys

values = {}
assignment_re = re.compile(r"(\w+)\s*<-\s*(.+)")
increment_re = re.compile(r"\(\s*(\w+)\s*\+\s*(\d+)\s*\)\s*mod\s*100")

for statement in sys.stdin.read().split(";"):
    statement = statement.strip()
    if not statement:
        continue

    match = assignment_re.fullmatch(statement)
    if not match:
        continue

    name, rhs = match.groups()
    if rhs.isdigit():
        values[name] = int(rhs)
    else:
        increment = increment_re.fullmatch(rhs)
        if increment:
            source, amount = increment.groups()
            values[name] = (values[source] + int(amount)) % 100

print(
    f"a ?= {values['a']}; b ?= {values['b']}; c ?= {values['c']}; "
    f"d ?= {values['d']}; TMP ?= {values['TMP']};"
)
